UPDATE tb_evento_corridas SET descricao='CORRIDA E CAMINHADA OUTUBRO ROSA<br>No dia 25 de outubro, o Corre Chupinguaia convida voc&ecirc; para um momento especial de esporte, sa&uacute;de, uni&atilde;o e conscientiza&ccedil;&atilde;o. A Corrida e Caminhada Outubro Rosa foi organizada para reunir corredores, caminhantes, fam&iacute;lias e toda a comunidade em uma manh&atilde; dedicada a incentivar a pr&aacute;tica de atividade f&iacute;sica e destacar a import&acirc;ncia do cuidado com a sa&uacute;de da mulher.<br>Mais do que correr, &eacute; cuidar. Mais do que caminhar, &eacute; incentivar. Juntos, vamos vestir essa causa e divulgar uma mensagem de preven&ccedil;&atilde;o, autocuidado e amor &agrave; vida.<br>Venha participar conosco&#x21; Seja correndo, caminhando ou apenas apoiando, voc&ecirc; faz parte dessa causa.<br>Corre Chupinguaia &mdash; um movimento que une pessoas e transforma vidas&#x21;<br><br>25 de outubro<br>Corrida e Caminhada Outubro Rosa<br>Data&#x3a; 25 de outubro<br>Largada&#x3a; 6h da manh&atilde;<br>Local&#x3a; em frente ao Sicredi<br>Percurso&#x3a; 5 km',descricao_en=NULL,descricao_es=NULL,descricao_traducoes_meta=NULL WHERE id_evento=48918;
